4. 引擎层设计 (Runtime Engine)
引擎充当 ORM (Object-Relational Mapper) 的角色，负责“欺骗”前端。
4.1 写入转换 (Write / Unboxing)
前端发来的是一个对象，后端要拆散存入数据库。
// Input: 前端提交的 JSON
const payload = {
  title: "服务器采购",
  price: { value: 5000.00, currency: "USD" } // 复合对象
};

async function insertRecord(tableSchema, payload) {
  const dbRow = {};

  tableSchema.columns.forEach(col => {
    const key = col.dataIndex;
    const value = payload[key];

    if (col.valueType === 'money') {
      if (value) {
        // 拆箱操作
        dbRow[key] = value.value;           // price = 5000
        dbRow[`${key}_cur`] = value.currency; // price_cur = "USD"
      } else {
        dbRow[key] = null;
        dbRow[`${key}_cur`] = null;
      }
    } else {
      // 普通字段
      dbRow[key] = value;
    }
  });

  // 生成 SQL: INSERT INTO ... (title, price, price_cur) VALUES ...
  return await db.insert(dbRow);
}

4.2 读取转换 (Read / Boxing)
数据库查出来是散的，后端要组装好发给前端。
// Input: 数据库查出的 Raw Data
const dbRows = [
  { id: 1, title: "服务器采购", price: 5000.00, price_cur: "USD" }
];

function transformRows(tableSchema, dbRows) {
  return dbRows.map(row => {
    const apiRow = { ...row };

    tableSchema.columns.forEach(col => {
      if (col.valueType === 'money') {
        const key = col.dataIndex;

        // 装箱操作：合并两个字段为一个对象
        apiRow[key] = {
          value: row[key],            // 5000
          currency: row[`${key}_cur`] // "USD"
        };

        // 清理掉伴生列，保证 API 纯净
        delete apiRow[`${key}_cur`];
      }
    });

    return apiRow;
  });
}

5. 查询构建器 (Query Builder)
解决“用户如何筛选”的问题。
用户在前端配置筛选器：{ field: "price", operator: ">", value: 100 }。
用户的直觉是“金额大于100”，他通常不管币种，或者默认指当前币种。
function buildWhereClause(filter) {
  const { field, operator, value } = filter;
  // 假设 schema 中 price 是 money 类型

  // 场景 1: 用户只查数值 (WHERE price > 100)
  // 这是最自然的 SQL 映射，直接查主列
  if (typeof value === 'number') {
    return `\`${field}\` ${operator} ${value}`;
  }

  // 场景 2: 用户精确查特定币种的金额 (WHERE price = 100 AND price_cur = 'USD')
  // 前端传来的 value 可能是 { value: 100, currency: 'USD' }
  if (typeof value === 'object') {
    return `(\`${field}\` ${operator} ${value.value} AND \`${field}_cur\` = '${value.currency}')`;
  }
}

